raph","content":[{"type":"text","text":"volumes beheersbaar zijn;"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"fouten zichtbaar en herstelbaar zijn;"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"volledige maatwerkcontrole weinig extra waarde toevoegt."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Wanneer maatwerk waarschijnlijk logischer wordt"}]},{"type":"paragraph","content":[{"type":"text","text":"Maatwerk wordt sterker wanneer:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"businessregels uniek zijn;"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"meerdere systemen complexe state delen;"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"hoge volumes spelen;"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"eigen UI nodig is;"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"recovery heel specifiek moet zijn;"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"observability veel dieper moet;"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"platformlimits knellen;"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"integratie een kernonderdeel van het product of bedrijfsproces is."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Wanneer hybride waarschijnlijk de beste oplossing is"}]},{"type":"paragraph","content":[{"type":"text","text":"Hybride is logisch wanneer je:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"kritieke transacties zelf wilt beheren;"}]}]},{"type":"listItem","content":[{"type":